/* Module 12 — Approval & Publishing */
export async function listReleaseProjects(workspaceId:string){const db=await getDb();const r=await db.request().input('ws',sql.UniqueIdentifier,workspaceId).query(`SELECT rp.ReleaseProjectId,rp.ContentProjectId,rp.PackagingVersionId,rp.Status,rp.ProgressPercent,rp.CurrentApprovalStep,rp.RequiredApprovalSteps,p.ContentCode,p.WorkingTitle,pv.VersionNumber PackagingVersion,(SELECT COUNT(*) FROM dbo.ReleaseChecks rc WHERE rc.ReleaseProjectId=rp.ReleaseProjectId AND rc.IsBlocking=1 AND rc.Status<>'PASSED') BlockingChecks,(SELECT COUNT(*) FROM dbo.PublishJobs pj WHERE pj.ReleaseProjectId=rp.ReleaseProjectId AND pj.Status='SCHEDULED') ScheduledJobs FROM dbo.ReleaseProjects rp JOIN dbo.ContentProjects p ON p.ContentProjectId=rp.ContentProjectId JOIN dbo.PackagingVersions pv ON pv.PackagingVersionId=rp.PackagingVersionId WHERE rp.WorkspaceId=@ws ORDER BY rp.UpdatedAt DESC`);return r.recordset}
export async function getReleaseWorkspace(workspaceId:string,projectId:string){const db=await getDb();let project=(await db.request().input('ws',sql.UniqueIdentifier,workspaceId).input('pid',sql.UniqueIdentifier,projectId).query(`SELECT TOP 1 rp.*,p.ContentCode,p.WorkingTitle,pv.VersionNumber PackagingVersion,pp.MasterVideoVersionId FROM dbo.ReleaseProjects rp JOIN dbo.ContentProjects p ON p.ContentProjectId=rp.ContentProjectId JOIN dbo.PackagingVersions pv ON pv.PackagingVersionId=rp.PackagingVersionId JOIN dbo.PackagingProjects pp ON pp.PackagingProjectId=pv.PackagingProjectId WHERE rp.WorkspaceId=@ws AND rp.ContentProjectId=@pid`)).recordset[0];if(!project){const approved=(await db.request().input('ws',sql.UniqueIdentifier,workspaceId).input('pid',sql.UniqueIdentifier,projectId).query(`SELECT TOP 1 pv.PackagingVersionId FROM dbo.PackagingVersions pv JOIN dbo.PackagingProjects pp ON pp.PackagingProjectId=pv.PackagingProjectId WHERE pp.WorkspaceId=@ws AND pp.ContentProjectId=@pid AND pv.Status='APPROVED' ORDER BY pv.VersionNumber DESC`)).recordset[0];if(!approved)return null;project=(await db.request().input('ws',sql.UniqueIdentifier,workspaceId).input('pid',sql.UniqueIdentifier,projectId).input('pv',sql.UniqueIdentifier,approved.PackagingVersionId).query(`INSERT dbo.ReleaseProjects(WorkspaceId,ContentProjectId,PackagingVersionId,Status,ProgressPercent,CurrentApprovalStep,RequiredApprovalSteps) OUTPUT INSERTED.* VALUES(@ws,@pid,@pv,'AWAITING_APPROVAL',10,1,2)`)).recordset[0];await db.request().input('rid',sql.UniqueIdentifier,project.ReleaseProjectId).query(`INSERT dbo.ReleaseApprovalSteps(ReleaseProjectId,StepNumber,StepKey,StepName,RequiredRoleKey,Status) VALUES(@rid,1,'CONTENT_REVIEW','Content & Packaging Review','CONTENT_MANAGER','PENDING'),(@rid,2,'FINAL_PUBLISHER','Final Publisher Approval','PUBLISHER','PENDING');INSERT dbo.ReleaseChecks(ReleaseProjectId,CheckKey,CheckName,Category,Severity,IsBlocking,Status) VALUES(@rid,'PACKAGE_LOCK','Approved packaging version locked','Governance','BLOCKING',1,'PASSED'),(@rid,'MASTER_ACCESS','Master media accessible','Asset','BLOCKING',1,'NEEDS_REVIEW'),(@rid,'THUMBNAIL_ACCESS','Primary thumbnail accessible','Asset','BLOCKING',1,'NEEDS_REVIEW'),(@rid,'COPYRIGHT','Copyright / licensing clearance','Compliance','BLOCKING',1,'NEEDS_REVIEW'),(@rid,'CAPTION','Required captions attached','Accessibility','HIGH',0,'NEEDS_REVIEW'),(@rid,'PLATFORM_CONNECTION','Publishing platform connection healthy','Integration','BLOCKING',1,'NEEDS_REVIEW'),(@rid,'SCHEDULE','Publishing date/time confirmed','Release','BLOCKING',1,'NEEDS_REVIEW')`);return await getReleaseWorkspace(workspaceId,projectId)}const rid=project.ReleaseProjectId;const [approvals,checks,connections,jobs,publications,activities]=await Promise.all([db.request().input('rid',sql.UniqueIdentifier,rid).query(`SELECT * FROM dbo.ReleaseApprovalSteps WHERE ReleaseProjectId=@rid ORDER BY StepNumber`),db.request().input('rid',sql.UniqueIdentifier,rid).query(`SELECT * FROM dbo.ReleaseChecks WHERE ReleaseProjectId=@rid ORDER BY CASE IsBlocking WHEN 1 THEN 0 ELSE 1 END,Category,CheckName`),db.request().input('ws',sql.UniqueIdentifier,workspaceId).query(`SELECT * FROM dbo.PublishingConnections WHERE WorkspaceId=@ws ORDER BY Platform`),db.request().input('rid',sql.UniqueIdentifier,rid).query(`SELECT pj.*,pp.ContentFormat,pp.Title,pc.ConnectionName,pc.AccountLabel FROM dbo.PublishJobs pj JOIN dbo.PlatformPackages pp ON pp.PlatformPackageId=pj.PlatformPackageId LEFT JOIN dbo.PublishingConnections pc ON pc.PublishingConnectionId=pj.PublishingConnectionId WHERE pj.ReleaseProjectId=@rid ORDER BY COALESCE(pj.ScheduledFor,'9999-12-31'),pj.Priority`),db.request().input('rid',sql.UniqueIdentifier,rid).query(`SELECT * FROM dbo.Publications WHERE ReleaseProjectId=@rid ORDER BY PublishedAt DESC`),db.request().input('rid',sql.UniqueIdentifier,rid).query(`SELECT * FROM dbo.ReleaseActivities WHERE ReleaseProjectId=@rid ORDER BY CreatedAt DESC`)]);return {project,approvals:approvals.recordset,checks:checks.recordset,connections:connections.recordset,jobs:jobs.recordset,publications:publications.recordset,activities:activities.recordset}}
export async function updateReleaseCheck(workspaceId:string,checkId:string,userId:string,input:any){const db=await getDb();const r=await db.request().input('ws',sql.UniqueIdentifier,workspaceId).input('id',sql.UniqueIdentifier,checkId).input('st',sql.NVarChar(30),input.status).input('ev',sql.NVarChar(sql.MAX),input.evidence||null).input('uid',sql.UniqueIdentifier,userId).query(`UPDATE rc SET Status=@st,Evidence=@ev,ResolvedByUserId=@uid,ResolvedAt=SYSUTCDATETIME(),UpdatedAt=SYSUTCDATETIME() OUTPUT INSERTED.* FROM dbo.ReleaseChecks rc JOIN dbo.ReleaseProjects rp ON rp.ReleaseProjectId=rc.ReleaseProjectId WHERE rc.ReleaseCheckId=@id AND rp.WorkspaceId=@ws`);return r.recordset[0]||null}
export async function decideReleaseApproval(workspaceId:string,projectId:string,userId:string,input:any){const db=await getDb();const ctx:any=await getReleaseWorkspace(workspaceId,projectId);if(!ctx)throw Object.assign(new Error('Approved packaging version required'),{statusCode:409});const step=ctx.approvals.find((x:any)=>x.ReleaseApprovalStepId===input.approvalStepId)||ctx.approvals.find((x:any)=>x.Status==='PENDING');if(!step)throw Object.assign(new Error('Approval step not found'),{statusCode:404});if(input.decision==='APPROVE'){const blockers=ctx.checks.filter((x:any)=>x.IsBlocking&&x.Status!=='PASSED');if(blockers.length)throw Object.assign(new Error(`Release approval blocked by ${blockers.length} unresolved control(s)`),{statusCode:409});const earlier=ctx.approvals.filter((x:any)=>x.StepNumber<step.StepNumber&&x.Status!=='APPROVED');if(earlier.length)throw Object.assign(new Error('Previous approval step must be approved first'),{statusCode:409})}const st=input.decision==='APPROVE'?'APPROVED':'RETURNED';await db.request().input('sid',sql.UniqueIdentifier,step.ReleaseApprovalStepId).input('st',sql.NVarChar(30),st).input('dec',sql.NVarChar(30),input.decision).input('comment',sql.NVarChar(sql.MAX),input.comment||null).input('uid',sql.UniqueIdentifier,userId).query(`UPDATE dbo.ReleaseApprovalSteps SET Status=@st,Decision=@dec,Comment=@comment,DecidedByUserId=@uid,DecidedAt=SYSUTCDATETIME(),UpdatedAt=SYSUTCDATETIME() WHERE ReleaseApprovalStepId=@sid`);if(st==='RETURNED'){await db.request().input('rid',sql.UniqueIdentifier,ctx.project.ReleaseProjectId).input('uid',sql.UniqueIdentifier,userId).input('comment',sql.NVarChar(sql.MAX),input.comment||null).query(`UPDATE dbo.ReleaseProjects SET Status='RETURNED',UpdatedAt=SYSUTCDATETIME() WHERE ReleaseProjectId=@rid;INSERT dbo.ReleaseActivities(ReleaseProjectId,ActivityType,Title,Details,ActorType,ActorUserId) VALUES(@rid,'RELEASE_RETURNED','Release returned for correction',@comment,'HUMAN',@uid)`);return {ok:true,status:'RETURNED'}}const remaining=ctx.approvals.filter((x:any)=>x.ReleaseApprovalStepId!==step.ReleaseApprovalStepId&&x.Status!=='APPROVED');if(!remaining.length){await db.request().input('rid',sql.UniqueIdentifier,ctx.project.ReleaseProjectId).input('pid',sql.UniqueIdentifier,projectId).input('uid',sql.UniqueIdentifier,userId).input('pvid',sql.UniqueIdentifier,ctx.project.PackagingVersionId).query(`UPDATE dbo.ReleaseProjects SET Status='APPROVED',ProgressPercent=85,ApprovedAt=SYSUTCDATETIME(),CurrentApprovalStep=RequiredApprovalSteps,UpdatedAt=SYSUTCDATETIME() WHERE ReleaseProjectId=@rid;UPDATE dbo.ProjectStageExecutions SET Status='COMPLETED',ProgressPercent=100,CompletedAt=SYSUTCDATETIME(),UpdatedAt=SYSUTCDATETIME() WHERE ContentProjectId=@pid AND WorkflowStageDefinitionId IN(SELECT WorkflowStageDefinitionId FROM dbo.WorkflowStageDefinitions WHERE StageKey='FINAL_APPROVAL');UPDATE dbo.ProjectStageExecutions SET Status='IN_PROGRESS',ProgressPercent=10,StartedAt=COALESCE(StartedAt,SYSUTCDATETIME()),UpdatedAt=SYSUTCDATETIME() WHERE ContentProjectId=@pid AND WorkflowStageDefinitionId IN(SELECT WorkflowStageDefinitionId FROM dbo.WorkflowStageDefinitions WHERE StageKey='PUBLISHING');INSERT dbo.ProjectVersions(ContentProjectId,VersionType,VersionNumber,SourceStageKey,Title,SnapshotJson,ChangeSummary,IsApproved,CreatedByUserId) VALUES(@pid,'RELEASE_PACKAGE',1,'FINAL_APPROVAL','Approved Release Package',JSON_OBJECT('packagingVersionId',CAST(@pvid AS NVARCHAR(36)),'releaseProjectId',CAST(@rid AS NVARCHAR(36))),'Final human release approval completed.',1,@uid);INSERT dbo.ReleaseActivities(ReleaseProjectId,ActivityType,Title,Details,ActorType,ActorUserId) VALUES(@rid,'FINAL_APPROVAL_COMPLETED','Final release approved','Release package unlocked for publishing jobs.','HUMAN',@uid);INSERT dbo.ProjectActivities(ContentProjectId,ActivityType,StageKey,Title,Details,ActorType,ActorUserId) VALUES(@pid,'FINAL_RELEASE_APPROVED','FINAL_APPROVAL','Final release approved','Publishing stage unlocked.','HUMAN',@uid)`)}else await db.request().input('rid',sql.UniqueIdentifier,ctx.project.ReleaseProjectId).input('n',sql.Int,step.StepNumber+1).query(`UPDATE dbo.ReleaseProjects SET CurrentApprovalStep=@n,ProgressPercent=55,UpdatedAt=SYSUTCDATETIME() WHERE ReleaseProjectId=@rid`);return {ok:true,status:remaining.length?'IN_REVIEW':'APPROVED'}}
export async function savePublishingConnection(workspaceId:string,input:any){const db=await getDb();const existing=(await db.request().input('ws',sql.UniqueIdentifier,workspaceId).input('platform',sql.NVarChar(60),input.platform).input('name',sql.NVarChar(200),input.connectionName).query(`SELECT TOP 1 PublishingConnectionId FROM dbo.PublishingConnections WHERE WorkspaceId=@ws AND Platform=@platform AND ConnectionName=@name`)).recordset[0];if(existing){const r=await db.request().input('id',sql.UniqueIdentifier,existing.PublishingConnectionId).input('label',sql.NVarChar(250),input.accountLabel||null).input('ext',sql.NVarChar(250),input.externalAccountId||null).input('st',sql.NVarChar(30),input.status||'CONNECTED').input('scopes',sql.NVarChar(sql.MAX),JSON.stringify(input.scopes||[])).input('cred',sql.NVarChar(500),input.credentialReference||null).query(`UPDATE dbo.PublishingConnections SET AccountLabel=@label,ExternalAccountId=@ext,Status=@st,ScopesJson=@scopes,CredentialReference=@cred,UpdatedAt=SYSUTCDATETIME() OUTPUT INSERTED.* WHERE PublishingConnectionId=@id`);return r.recordset[0]}const r=await db.request().input('ws',sql.UniqueIdentifier,workspaceId).input('platform',sql.NVarChar(60),input.platform).input('name',sql.NVarChar(200),input.connectionName).input('label',sql.NVarChar(250),input.accountLabel||null).input('ext',sql.NVarChar(250),input.externalAccountId||null).input('st',sql.NVarChar(30),input.status||'CONNECTED').input('scopes',sql.NVarChar(sql.MAX),JSON.stringify(input.scopes||[])).input('cred',sql.NVarChar(500),input.credentialReference||null).query(`INSERT dbo.PublishingConnections(WorkspaceId,Platform,ConnectionName,AccountLabel,ExternalAccountId,Status,ScopesJson,CredentialReference) OUTPUT INSERTED.* VALUES(@ws,@platform,@name,@label,@ext,@st,@scopes,@cred)`);return r.recordset[0]}
export async function createPublishJob(workspaceId:string,projectId:string,userId:string,input:any){const db=await getDb();const ctx:any=await getReleaseWorkspace(workspaceId,projectId);if(!ctx)throw Object.assign(new Error('Release project not found'),{statusCode:404});const pp=(await db.request().input('pvid',sql.UniqueIdentifier,ctx.project.PackagingVersionId).input('platform',sql.NVarChar(60),input.platform).query(`SELECT TOP 1 ppkg.PlatformPackageId,ppkg.Status FROM dbo.PlatformPackages ppkg JOIN dbo.PackagingVersions pv ON pv.PackagingProjectId=ppkg.PackagingProjectId WHERE pv.PackagingVersionId=@pvid AND ppkg.Platform=@platform ORDER BY ppkg.UpdatedAt DESC`)).recordset[0];if(!pp)throw Object.assign(new Error('Platform package not found in approved packaging project'),{statusCode:404});const conn=input.publishingConnectionId||null;const status=ctx.project.Status==='APPROVED'?(input.scheduledFor?'SCHEDULED':'QUEUED'):'DRAFT';const r=await db.request().input('ws',sql.UniqueIdentifier,workspaceId).input('rid',sql.UniqueIdentifier,ctx.project.ReleaseProjectId).input('pp',sql.UniqueIdentifier,pp.PlatformPackageId).input('conn',sql.UniqueIdentifier,conn).input('platform',sql.NVarChar(60),input.platform).input('op',sql.NVarChar(30),input.operation||'PUBLISH').input('st',sql.NVarChar(30),status).input('sched',sql.DateTime2,input.scheduledFor?new Date(input.scheduledFor):null).input('manifest',sql.NVarChar(sql.MAX),JSON.stringify(input.manifest||{})).input('uid',sql.UniqueIdentifier,userId).query(`INSERT dbo.PublishJobs(WorkspaceId,ReleaseProjectId,PlatformPackageId,PublishingConnectionId,Platform,Operation,Status,ScheduledFor,RequestManifestJson,CreatedByUserId) OUTPUT INSERTED.* VALUES(@ws,@rid,@pp,@conn,@platform,@op,@st,@sched,@manifest,@uid)`);return r.recordset[0]}
export async function controlPublishJob(workspaceId:string,jobId:string,userId:string,input:any){const db=await getDb();const job=(await db.request().input('ws',sql.UniqueIdentifier,workspaceId).input('id',sql.UniqueIdentifier,jobId).query(`SELECT pj.*,rp.Status ReleaseStatus FROM dbo.PublishJobs pj JOIN dbo.ReleaseProjects rp ON rp.ReleaseProjectId=pj.ReleaseProjectId WHERE pj.WorkspaceId=@ws AND pj.PublishJobId=@id`)).recordset[0];if(!job)return null;let st=job.Status;if(input.action==='CANCEL')st='CANCELLED';if(input.action==='RETRY'){if(job.ReleaseStatus!=='APPROVED')throw Object.assign(new Error('Final release approval required before retry'),{statusCode:409});st='QUEUED'}if(input.action==='QUEUE'){if(job.ReleaseStatus!=='APPROVED')throw Object.assign(new Error('Final release approval required before queueing'),{statusCode:409});st=job.ScheduledFor?'SCHEDULED':'QUEUED'}const r=await db.request().input('id',sql.UniqueIdentifier,jobId).input('st',sql.NVarChar(30),st).query(`UPDATE dbo.PublishJobs SET Status=@st,ErrorCode=NULL,ErrorMessage=NULL,UpdatedAt=SYSUTCDATETIME() OUTPUT INSERTED.* WHERE PublishJobId=@id`);return r.recordset[0]}
export async function registerPublication(workspaceId:string,jobId:string,userId:string,input:any){const db=await getDb();const job=(await db.request().input('ws',sql.UniqueIdentifier,workspaceId).input('id',sql.UniqueIdentifier,jobId).query(`SELECT pj.*,rp.ContentProjectId,rp.ReleaseProjectId FROM dbo.PublishJobs pj JOIN dbo.ReleaseProjects rp ON rp.ReleaseProjectId=pj.ReleaseProjectId WHERE pj.WorkspaceId=@ws AND pj.PublishJobId=@id`)).recordset[0];if(!job)throw Object.assign(new Error('Publish job not found'),{statusCode:404});const r=await db.request().input('ws',sql.UniqueIdentifier,workspaceId).input('pid',sql.UniqueIdentifier,job.ContentProjectId).input('rid',sql.UniqueIdentifier,job.ReleaseProjectId).input('jid',sql.UniqueIdentifier,jobId).input('platform',sql.NVarChar(60),job.Platform).input('ext',sql.NVarChar(500),input.externalPublicationId).input('url',sql.NVarChar(1500),input.publicationUrl||null).input('title',sql.NVarChar(500),input.publishedTitle||null).input('at',sql.DateTime2,input.publishedAt?new Date(input.publishedAt):new Date()).input('vis',sql.NVarChar(40),input.visibility||null).input('meta',sql.NVarChar(sql.MAX),JSON.stringify(input.metadata||{})).query(`INSERT dbo.Publications(WorkspaceId,ContentProjectId,ReleaseProjectId,PublishJobId,Platform,ExternalPublicationId,PublicationUrl,PublishedTitle,PublishedAt,Visibility,MetadataSnapshotJson) OUTPUT INSERTED.* VALUES(@ws,@pid,@rid,@jid,@platform,@ext,@url,@title,@at,@vis,@meta);UPDATE dbo.PublishJobs SET Status='PUBLISHED',ExternalPublicationId=@ext,PublicationUrl=@url,CompletedAt=@at,UpdatedAt=SYSUTCDATETIME() WHERE PublishJobId=@jid`);await db.request().input('rid',sql.UniqueIdentifier,job.ReleaseProjectId).input('pid',sql.UniqueIdentifier,job.ContentProjectId).input('jid',sql.UniqueIdentifier,jobId).input('platform',sql.NVarChar(60),job.Platform).input('ext',sql.NVarChar(500),input.externalPublicationId).input('url',sql.NVarChar(1500),input.publicationUrl||null).input('uid',sql.UniqueIdentifier,userId).query(`UPDATE dbo.ReleaseProjects SET Status='PUBLISHED',ProgressPercent=100,ReleasedAt=SYSUTCDATETIME(),UpdatedAt=SYSUTCDATETIME() WHERE ReleaseProjectId=@rid;UPDATE dbo.ProjectStageExecutions SET Status='COMPLETED',ProgressPercent=100,CompletedAt=SYSUTCDATETIME(),UpdatedAt=SYSUTCDATETIME() WHERE ContentProjectId=@pid AND WorkflowStageDefinitionId IN(SELECT WorkflowStageDefinitionId FROM dbo.WorkflowStageDefinitions WHERE StageKey='PUBLISHING');UPDATE dbo.ProjectStageExecutions SET Status='IN_PROGRESS',ProgressPercent=5,StartedAt=COALESCE(StartedAt,SYSUTCDATETIME()),UpdatedAt=SYSUTCDATETIME() WHERE ContentProjectId=@pid AND WorkflowStageDefinitionId IN(SELECT WorkflowStageDefinitionId FROM dbo.WorkflowStageDefinitions WHERE StageKey='PERFORMANCE_MONITORING');INSERT dbo.ProjectHandoffs(ContentProjectId,FromStageKey,ToStageKey,OutputType,OutputReference,PayloadJson,Status,CreatedByUserId) VALUES(@pid,'PUBLISHING','PERFORMANCE_MONITORING','Published Content',@ext,JSON_OBJECT('publishJobId',CAST(@jid AS NVARCHAR(36)),'platform',@platform,'externalPublicationId',@ext,'publicationUrl',@url),'READY',@uid);INSERT dbo.ReleaseActivities(ReleaseProjectId,ActivityType,Title,Details,ActorType,ActorUserId) VALUES(@rid,'PUBLISHED','Content published',CONCAT(@platform,' publication completed: ',COALESCE(@url,@ext)),'SYSTEM',@uid);INSERT dbo.ProjectActivities(ContentProjectId,ActivityType,StageKey,Title,Details,ActorType,ActorUserId) VALUES(@pid,'CONTENT_PUBLISHED','PUBLISHING','Content published','Publication identity captured and handed to Performance Monitoring.','SYSTEM',@uid)`);return r.recordset[0]}
